def find_nth_good_integer(N: int) -> int:
    def is_good_integer(x: int) -> bool:
        while x > 0:
            if x % 10 not in {0, 2, 4, 6, 8}:
                return False
            x //= 10
        return True

    count = 0
    current = 0
    while True:
        if is_good_integer(current):
            count += 1
            if count == N:
                return current
        current += 1
